@app.route("/api/extract-versions", methods=["POST"])
def extract_versions():
    """
    Extract important versions from Google Docs document

    Expected JSON body:
    {
        "url": "https://docs.google.com/document/d/...",
        "description": "Optional description of what the document was about"
    }
    """
    try:
        data = request.get_json()

        if not data or "url" not in data:
            return jsonify({"error": "Missing required field: url"}), 400

        document_url = data["url"].strip()
        description = data.get("description", "").strip() or None

        if not document_url:
            return jsonify({"error": "URL cannot be empty"}), 400

        # Validate URL format - accept both Docs and Slides
        if (
            "docs.google.com/document" not in document_url
            and "docs.google.com/presentation" not in document_url
        ):
            return jsonify({"error": "Invalid Google Docs or Slides URL format"}), 400

        logging.info(f"Starting analysis for URL: {document_url}")
        if description:
            logging.info(f"Document description provided: {description[:100]}...")

