@app.route("/api/analysis/load-existing/<analysis_id>", methods=["GET"])
def load_existing_analysis(analysis_id):
    """
    Load the actual content of an existing analysis

    Returns the full workflow_map content from the analysis file
    """
    try:
        logging.info(f"Loading existing analysis: {analysis_id}")

        # Load analysis registry to find the file path
        registry_path = Path("generated/cache/analysis_registry.json")

        if not registry_path.exists():
            return jsonify({"error": "Analysis registry not found"}), 404

        with open(registry_path, "r", encoding="utf-8") as f:
            registry = json.load(f)

        # Find the analysis
        analysis_info = None
        for analysis in registry.get("analyses", []):
            if analysis["analysis_id"] == analysis_id:
                analysis_info = analysis
                break

        if not analysis_info:
            return jsonify({"error": "Analysis not found"}), 404

        # Load the actual analysis file
        analysis_file_path = Path("generated") / analysis_info["file_path"]

        if not analysis_file_path.exists():
            return jsonify({"error": "Analysis file not found"}), 404

        with open(analysis_file_path, "r", encoding="utf-8") as f:
            workflow_content = f.read()

        # Update usage count
        analysis_info["usage_count"] = analysis_info.get("usage_count", 0) + 1
        with open(registry_path, "w", encoding="utf-8") as f:
            json.dump(registry, f, indent=2)

        return jsonify(
            {
                "job_id": analysis_id,
                "status": "complete",
                "workflow_map": workflow_content,
                "error": None,
                "from_cache": True,
            }
        )

    except Exception as e:
        logging.error(f"Error in load_existing_analysis: {str(e)}")
        return jsonify({"error": f"Internal server error: {str(e)}"}), 500


@app.route("/api/analysis/find-existing", methods=["POST"])
def find_existing_analyses():
    """
    Find existing analyses for a given set of document IDs

    Expected JSON body:
    {
        "document_ids": ["doc_id_1", "doc_id_2", ...]
    }
    """
    try:
        data = request.get_json()

        if not data or "document_ids" not in data:
            return jsonify({"error": "Missing required field: document_ids"}), 400

        document_ids = data["document_ids"]

        if not isinstance(document_ids, list) or len(document_ids) == 0:
            return jsonify({"error": "document_ids must be a non-empty array"}), 400

        # Sort document IDs for consistent matching
        sorted_doc_ids = sorted(document_ids)

        logging.info(f"Finding existing analyses for documents: {sorted_doc_ids}")

        # Load analysis registry
        registry_path = Path("generated/cache/analysis_registry.json")
        existing_analyses = []

        if registry_path.exists():
            with open(registry_path, "r", encoding="utf-8") as f:
                registry = json.load(f)

            # Find matching analyses
            for analysis in registry.get("analyses", []):
                analysis_doc_ids = sorted(analysis.get("document_ids", []))

                # Check for exact match
                if analysis_doc_ids == sorted_doc_ids:
                    existing_analyses.append(
                        {
                            "analysis_id": analysis["analysis_id"],
                            "document_titles": analysis["document_titles"],
                            "created_at": analysis["created_at"],
                            "pattern_preview": analysis["pattern_preview"],
                            "usage_count": analysis["usage_count"],
                        }
                    )

        return jsonify(
            {
                "existing_analyses": existing_analyses,
                "total_found": len(existing_analyses),
            }
        )

    except Exception as e:
        logging.error(f"Error in find_existing_analyses: {str(e)}")
        return jsonify({"error": f"Internal server error: {str(e)}"}), 500


