@app.route("/api/working-session/<session_id>/create-comment", methods=["POST"])
def create_user_comment(session_id):
    """
    Create a user-initiated comment on selected text

    Expected JSON body:
    {
        "selected_text": "Years of pushing forward...",
        "paragraph_index": 2,
        "start_offset": 150,
        "end_offset": 200,
        "user_question": "How can I make this stronger?"
    }
    """
    try:
        data = request.get_json()

        required_fields = [
            "selected_text",
            "paragraph_index",
            "start_offset",
            "end_offset",
            "user_question",
        ]
        for field in required_fields:
            if field not in data:
