def write_to_google_doc(session_id):
    """
    Push local content back to Google Docs

    Expected JSON body:
    {
        "paragraphs": [
            {
                "index": 0,
                "text": "paragraph text",
                "formatting": {
                    "bold": false,
                    "italic": false,
                    "underline": false,
                    "bullet": false,
                    "bullet_nesting": 0
                }
            }
        ]
    }
    """
    try:
        data = request.get_json()

        # Support both old format (content_html) and new format (paragraphs JSON string)
        if "content_html" in data:
            # Check if it's actually JSON string
            content = data["content_html"]
            try:
                parsed_content = json.loads(content)
                if "paragraphs" in parsed_content:
                    paragraphs = parsed_content["paragraphs"]
                else:
                    # Old HTML format, convert to simple paragraph structure
                    return (
                        jsonify(
                            {
                                "error": "HTML format no longer supported, please use JSON paragraphs"
                            }
                        ),
                        400,
                    )
            except json.JSONDecodeError:
                # Old HTML string format
                return (
                    jsonify(
                        {
                            "error": "HTML format no longer supported, please use JSON paragraphs"
                        }
                    ),
                    400,
                )
        elif "paragraphs" in data:
            paragraphs = data["paragraphs"]
        else:
            return jsonify({"error": "Missing required field: paragraphs"}), 400

        logging.info(
            f"Writing {len(paragraphs)} paragraphs to Google Doc for session {session_id}"
        )

        # Find session folder
        session_folder = working_doc_service._find_session_folder(session_id)
        if not session_folder:
            return jsonify({"error": "Session not found"}), 404

        # Load session metadata to get doc_id
        metadata_file = session_folder / "session_metadata.json"
        with open(metadata_file, "r", encoding="utf-8") as f:
            session_metadata = json.load(f)

        doc_id = session_metadata.get("working_doc_id")

        # Write to Google Docs using paragraph structure
        write_result = google_docs_service.write_document_paragraphs(doc_id, paragraphs)

        if write_result.get("error"):
            return (
                jsonify(
                    {"error": f"Failed to write to Google Doc: {write_result['error']}"}
                ),
                400,
            )

        # Update session metadata
        session_metadata["last_google_doc_write"] = datetime.now().isoformat()

        with open(metadata_file, "w", encoding="utf-8") as f:
            json.dump(session_metadata, f, indent=2)

        logging.info(
            f"Successfully wrote {len(paragraphs)} paragraphs to document {doc_id}"
        )

        return jsonify(
            {
                "status": "success",
                "doc_url": f"https://docs.google.com/document/d/{doc_id}",
                "written_at": datetime.now().isoformat(),
            }
        )

    except Exception as e:
        logging.error(f"Error in write_to_google_doc: {str(e)}")
        return jsonify({"error": f"Internal server error: {str(e)}"}), 500


