def _update_archive_index(
    archives_folder: Path,
    timestamp: str,
    reason: str,
    comment_count: int,
    paragraph_count: int,
    changes: str
):
    """
    Update the archive index with new archive entry

    Args:
        archives_folder: Path to archives subfolder
        timestamp: Timestamp of the archive (e.g. "20251013_232249")
        reason: Reason for archiving (e.g. "new_comments_generated", "user_edited_document")
        comment_count: Number of comments in this archive
        paragraph_count: Number of paragraphs in document
        changes: Description of what changed
    """
    index_file = archives_folder / "index.json"

    # Load or create index
    if index_file.exists():
        with open(index_file, "r", encoding="utf-8") as f:
            index_data = json.load(f)
    else:
        index_data = {
            "created_at": datetime.now().isoformat(),
            "total_archives": 0,
            "archives": []
        }

    # Add new archive entry
    archive_entry = {
        "timestamp": timestamp,
        "archived_at": datetime.now().isoformat(),
        "reason": reason,
        "comments_file": f"comments_archive_{timestamp}.json",
        "document_file": f"document_snapshot_archive_{timestamp}.json",
        "metadata": {
            "comment_count": comment_count,
            "paragraph_count": paragraph_count,
            "changes": changes
        }
    }

    index_data["archives"].append(archive_entry)
    index_data["total_archives"] = len(index_data["archives"])
    index_data["last_updated"] = datetime.now().isoformat()

    # Save index
    with open(index_file, "w", encoding="utf-8") as f:
        json.dump(index_data, f, indent=2)

    logging.info(f"Updated archive index with entry for {timestamp}")


