# Comment System Endpoints


@app.route("/api/working-session/<session_id>/generate-comments", methods=["POST"])
def generate_comments(session_id):
    """
    Generate AI comments for current document state

    Optional JSON body:
    {
        "force_regenerate": false
    }
    """
    try:
        data = request.get_json() or {}
        force_regenerate = data.get("force_regenerate", False)

        logging.info(f"Generating comments for session: {session_id}")

        # Find session folder
        session_folder = working_doc_service._find_session_folder(session_id)
        if not session_folder:
            return jsonify({"error": "Session not found"}), 404

        # Check if existing comments exist and should be loaded
        comments_file = session_folder / "comments.json"
        snapshot_file = session_folder / "document_snapshot.json"

        if not force_regenerate and comments_file.exists() and snapshot_file.exists():
            logging.info(f"Loading existing comments for session {session_id}")

            try:
                with open(comments_file, "r", encoding="utf-8") as f:
                    comments_data = json.load(f)

                with open(snapshot_file, "r", encoding="utf-8") as f:
                    snapshot_data = json.load(f)

                return jsonify(
                    {
                        "status": "success",
                        "comments": comments_data.get("comments", []),
                        "document_snapshot": snapshot_data,
                        "generated_at": comments_data.get("generated_at", ""),
                    }
                )
            except Exception as e:
                logging.warning(
                    f"Failed to load existing comments: {str(e)}, regenerating..."
                )
                # Fall through to regenerate if loading fails

        # Load session metadata
        metadata_file = session_folder / "session_metadata.json"
        with open(metadata_file, "r", encoding="utf-8") as f:
            session_metadata = json.load(f)

        doc_id = session_metadata.get("working_doc_id")
        analysis_id = session_metadata.get("analysis_used")

        # Get current document content as structured paragraphs (clean, no empty paragraphs)
        structured_result = google_docs_service.get_document_structured(doc_id)
        if structured_result.get("error"):
            return (
                jsonify(
                    {
                        "error": f"Failed to get document content: {structured_result['error']}"
                    }
                ),
                400,
            )

        paragraphs = structured_result.get("paragraphs", [])

        logging.info(f"Retrieved {len(paragraphs)} clean paragraphs from Google Docs")

        # Load analysis context
        analysis_context = working_doc_service._load_analysis_context(analysis_id)
        workflow_checkpoints = analysis_context.get("workflow_checkpoints", "")

        # Get current phase
        current_phase = session_metadata.get("phase_analysis", {})

        # Generate comments with detailed error tracking
        try:
            logging.info(
                f"About to call generate_phase_comments with structured paragraphs"
            )
            logging.info(
                f"current_phase type: {type(current_phase)}, value: {current_phase}"
            )
            logging.info(f"analysis_id: {analysis_id}")

            result = comment_service.generate_phase_comments(
                paragraphs, current_phase, workflow_checkpoints, analysis_id, doc_id
            )

            if result["status"] == "error":
                return jsonify({"error": result["error"]}), 400

        except Exception as e:
            import traceback

            error_trace = traceback.format_exc()
            logging.error(f"Exception in generate_phase_comments: {str(e)}")
            logging.error(f"Full traceback:\n{error_trace}")
            return (
                jsonify(
                    {"error": f"Internal error: {str(e)}", "traceback": error_trace}
                ),
                500,
            )

        # Archive existing comments before saving new ones
        comments_file = session_folder / "comments.json"
        snapshot_file = session_folder / "document_snapshot.json"

        if comments_file.exists():
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")

            # Create archives subfolder
            archives_folder = session_folder / "archives"
            archives_folder.mkdir(exist_ok=True)

            # Archive comments
            archive_comments = archives_folder / f"comments_archive_{timestamp}.json"
            comments_file.rename(archive_comments)
            logging.info(f"Archived comments to archives/{archive_comments.name}")

            # Archive document snapshot
            if snapshot_file.exists():
                archive_snapshot = (
                    archives_folder / f"document_snapshot_archive_{timestamp}.json"
                )
                snapshot_file.rename(archive_snapshot)
                logging.info(f"Archived snapshot to archives/{archive_snapshot.name}")

            # Update archive index
            _update_archive_index(
                archives_folder,
                timestamp,
                reason="new_comments_generated",
                comment_count=len(result["comments"]),
                paragraph_count=len(paragraphs),
                changes="Generated new AI writing suggestions"
            )

        # Save comments and document snapshot
        comments_data = {
            "session_id": session_id,
            "generated_at": datetime.now().isoformat(),
            "document_phase": current_phase.get("current_phase", "Unknown Phase"),
            "comments": result["comments"],
            "total_comments": len(result["comments"]),
            "resolved_count": 0,
            "active_count": len(result["comments"]),
        }

        with open(comments_file, "w", encoding="utf-8") as f:
            json.dump(comments_data, f, indent=2)

        # Save document snapshot with structured paragraphs
        snapshot_data = {
            "captured_at": datetime.now().isoformat(),
            "paragraphs": paragraphs,
            "word_count": result["document_structure"]["word_count"],
            "paragraph_count": result["document_structure"]["total_paragraphs"],
        }

        with open(snapshot_file, "w", encoding="utf-8") as f:
            json.dump(snapshot_data, f, indent=2)

        # Update session metadata
        session_metadata["has_active_comments"] = True
        session_metadata["last_comment_generation"] = datetime.now().isoformat()
        session_metadata["comment_summary"] = {
            "total_generated": len(result["comments"]),
            "currently_active": len(result["comments"]),
            "resolved": 0,
        }

        with open(metadata_file, "w", encoding="utf-8") as f:
            json.dump(session_metadata, f, indent=2)

        logging.info(
            f"Generated {len(result['comments'])} comments for session {session_id}"
        )

        return jsonify(
            {
                "status": "success",
                "comments": result["comments"],
                "document_snapshot": snapshot_data,
                "generated_at": datetime.now().isoformat(),
            }
        )

    except Exception as e:
        logging.error(f"Error in generate_comments: {str(e)}")
        return jsonify({"error": f"Internal server error: {str(e)}"}), 500


