def create_user_comment(session_id):
    """
    Create a user-initiated comment on selected text

    Expected JSON body:
    {
        "selected_text": "Years of pushing forward...",
        "paragraph_index": 2,
        "start_offset": 150,
        "end_offset": 200,
        "user_question": "How can I make this stronger?"
    }
    """
    try:
        data = request.get_json()

        required_fields = [
            "selected_text",
            "paragraph_index",
            "start_offset",
            "end_offset",
            "user_question",
        ]
        for field in required_fields:
            if field not in data:
                return jsonify({"error": f"Missing required field: {field}"}), 400

        selected_text = data["selected_text"]
        paragraph_index = data["paragraph_index"]
        start_offset = data["start_offset"]
        end_offset = data["end_offset"]
        user_question = data["user_question"].strip()

        if not user_question:
            return jsonify({"error": "user_question cannot be empty"}), 400

        logging.info(f"Creating user comment for session {session_id}")

        # Find session folder
        session_folder = working_doc_service._find_session_folder(session_id)
        if not session_folder:
            return jsonify({"error": "Session not found"}), 404

        # Load session metadata for phase context
        metadata_file = session_folder / "session_metadata.json"
        with open(metadata_file, "r", encoding="utf-8") as f:
            session_metadata = json.load(f)

        phase_analysis = session_metadata.get("phase_analysis", {})
        analysis_id = session_metadata.get("analysis_used")

        # Load workflow checkpoints
        analysis_context = working_doc_service._load_analysis_context(analysis_id)
        workflow_checkpoints = analysis_context.get("workflow_checkpoints", "")

        # Create comment
        result = comment_service.create_user_comment(
            session_folder,
            selected_text,
            paragraph_index,
            start_offset,
            end_offset,
            user_question,
            phase_analysis,
            workflow_checkpoints,
        )

        if "error" in result:
            return jsonify({"error": result["error"]}), 400

        logging.info(f"Created user comment {result['comment']['id']}")

        return jsonify(result)

    except Exception as e:
        logging.error(f"Error in create_user_comment: {str(e)}")
        return jsonify({"error": f"Internal server error: {str(e)}"}), 500


